export const peopleExpansion: ReferenceEntry[] = rows.map((row) => {
  const supportedKeys = keys.filter((key, index) => row.values[index] !== 50 && row.evidence[key] !== undefined);
  const unsupportedKeys = keys.filter((key, index) => row.values[index] !== 50 && row.evidence[key] === undefined);
  const axisEvidence = Object.fromEntries(supportedKeys.map((key) => {
    const value = row.values[keys.indexOf(key)];
    const pole = poles[key][value > 50 ? 0 : 1];
    return [key, {
      sourceTitles: [row.title],
      rationale: `${row.note} ${row.rationale} A direção editorial deste eixo é ${pole}, com valor aproximado do recorte da fonte; ela não mede opinião privada.`,
    }];
  }));
  const evidence = Object.fromEntries(supportedKeys.map((key) => [key, row.evidence[key]]));
  const vec = Object.fromEntries(keys.map((key, index) => [key, unsupportedKeys.includes(key) ? 50 : row.values[index]])) as Record<AxisKey, number>;
  return {
    id: row.id,
    kind: 'person',
    category: row.category,
    name: row.name,
    period: row.period,
    vec,
    rationale: row.rationale,
    caveats: row.caveats,
    sources: [{ title: row.title, url: row.url, note: row.note }],
    evidence,
    axisEvidence,
  };
});
